  #region Enums
  /// <summary>
  /// 프로토콜 버전. 옛 클라이언트를 받을 수 없게 패킷의 뜻이 바뀌면 CURRENT를 올린다.
  /// 필드를 더하기만 하면 protobuf가 모르는 필드를 건너뛰므로 올리지 않는다.
  /// </summary>
  public enum ProtocolVersion {
    [pbr::OriginalName("PROTOCOL_VERSION_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// 2: 로그인과 월드에 들어가기를 나눴다(계정 하나에 캐릭터 여럿, 2026-11-11).
    /// </summary>
    [pbr::OriginalName("PROTOCOL_VERSION_CURRENT")] Current = 2,
  }

  /// <summary>
  /// 서버와 두 클라이언트가 함께 쓰는 수. Protobuf에는 상수가 없어서 enum 값으로 두고, C#과 C++이 여기서 생성된다.
  /// </summary>
  public enum Constant {
    [pbr::OriginalName("CONSTANT_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// 1 m를 나눈 좌표 칸 수.
    /// </summary>
    [pbr::OriginalName("CONSTANT_UNITS_PER_METER")] UnitsPerMeter = 32,
    /// <summary>
    /// 맵의 반 너비(m). x, z는 이 거리 안이다.
    /// </summary>
    [pbr::OriginalName("CONSTANT_MAP_HALF_EXTENT_METERS")] MapHalfExtentMeters = 1024,
    /// <summary>
    /// 한 바퀴를 나눈 yaw 칸 수. yaw는 이보다 작다.
    /// </summary>
    [pbr::OriginalName("CONSTANT_YAW_STEPS")] YawSteps = 256,
    /// <summary>
    /// 서버의 초당 틱 수. EntityMoves.tick이 틱마다 1씩 오른다.
    /// </summary>
    [pbr::OriginalName("CONSTANT_TICKS_PER_SECOND")] TicksPerSecond = 20,
    /// <summary>
    /// 최대 이동 속도(m/s). 서버가 검증하고 클라이언트의 화면도 쓰는 수라 데이터가 아니라 여기에 둔다.
    /// </summary>
    [pbr::OriginalName("CONSTANT_MAX_SPEED_METERS_PER_SECOND")] MaxSpeedMetersPerSecond = 6,
    /// <summary>
    /// 클라이언트가 Ping을 보내는 간격(초).
    /// </summary>
    [pbr::OriginalName("CONSTANT_PING_INTERVAL_SECONDS")] PingIntervalSeconds = 5,
    /// <summary>
    /// 이 시간(초) 동안 아무것도 받지 못하면 서버도 클라이언트도 연결이 죽었다고 보고 끊는다.
    /// </summary>
    [pbr::OriginalName("CONSTANT_IDLE_TIMEOUT_SECONDS")] IdleTimeoutSeconds = 15,
    /// <summary>
    /// 계정 하나가 만들 수 있는 캐릭터 수.
    /// </summary>
    [pbr::OriginalName("CONSTANT_MAX_CHARACTERS")] MaxCharacters = 4,
    /// <summary>
    /// 퀵슬롯의 칸 수.
    /// </summary>
    [pbr::OriginalName("CONSTANT_QUICKSLOT_COUNT")] QuickslotCount = 8,
    /// <summary>
    /// 파티의 최대 인원(42).
    /// </summary>
    [pbr::OriginalName("CONSTANT_MAX_PARTY_SIZE", PreferredAlias = false)] MaxPartySize = 5,
  }

  /// <summary>
  /// 로그인의 결과.
  /// </summary>
  public enum LoginResultCode {
    /// <summary>
    /// 로그인했다. 이어서 CharacterList가 온다.
    /// </summary>
    [pbr::OriginalName("LOGIN_RESULT_CODE_OK")] Ok = 0,
    /// <summary>
    /// 로그인 ID의 형식이 맞지 않는다.
    /// </summary>
    [pbr::OriginalName("LOGIN_RESULT_CODE_INVALID_LOGIN_ID")] InvalidLoginId = 1,
    /// <summary>
    /// 클라이언트와 서버의 프로토콜 버전이 다르다. 클라이언트를 업데이트해야 한다.
    /// </summary>
    [pbr::OriginalName("LOGIN_RESULT_CODE_VERSION_MISMATCH")] VersionMismatch = 2,
    /// <summary>
    /// 동시 접속이 가득 찼다.
    /// </summary>
    [pbr::OriginalName("LOGIN_RESULT_CODE_SERVER_FULL")] ServerFull = 3,
    /// <summary>
    /// 클라이언트와 서버의 기획 데이터(테이블, 맵)가 다르다. 클라이언트를 업데이트해야 한다.
    /// </summary>
    [pbr::OriginalName("LOGIN_RESULT_CODE_DATA_MISMATCH")] DataMismatch = 4,
  }

  /// <summary>
  /// 서버가 연결을 끊는 까닭.
  /// </summary>
  public enum KickReason {
    [pbr::OriginalName("KICK_REASON_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// 같은 ID가 다른 연결에서 로그인했다. 예전 연결을 끊는다.
    /// </summary>
    [pbr::OriginalName("KICK_REASON_DUPLICATE_LOGIN")] DuplicateLogin = 1,
    /// <summary>
    /// 서버가 내려간다.
    /// </summary>
    [pbr::OriginalName("KICK_REASON_SERVER_SHUTDOWN")] ServerShutdown = 2,
    /// <summary>
