    /// </summary>
    [pbr::OriginalName("KICK_REASON_MALFORMED_PACKET")] MalformedPacket = 3,
    /// <summary>
    /// CONSTANT_IDLE_TIMEOUT_SECONDS 동안 아무것도 보내지 않았다.
    /// </summary>
    [pbr::OriginalName("KICK_REASON_IDLE_TIMEOUT")] IdleTimeout = 4,
    /// <summary>
    /// 요청을 너무 자주 보냈다(Constants의 빈도 제한. 버리는 일이 이어진 시간이 끊는 시간을 넘음).
    /// </summary>
    [pbr::OriginalName("KICK_REASON_RATE_LIMITED")] RateLimited = 5,
    /// <summary>
    /// 서버가 이 연결의 요청을 처리하다 오류가 났다(39). 그 캐릭터는 마지막으로 저장 큐에 넣은 상태로 돌아간다.
    /// </summary>
    [pbr::OriginalName("KICK_REASON_SERVER_ERROR")] ServerError = 6,
  }

